sys_ui_page.client_script:
function confirmBtn() {
    var num = g_form.getValue('num');
    var sys_id = g_form.getUniqueValue();
    var name = g_form.getValue('name');
    var ga = new GlideAjax('addNumberBtn'); 
    ga.addParam('sysparm_name','addNumber');
    ga.addParam('sysparm_num',num);
    // ga.addParam('sysparm_sys_name',name);
    ga.addParam('sysparm_sys_id',sys_id);
    ga.getXMLAnswer(function(response){
        if(response){
            top.window.parent.location.reload();
        }
    });
}

function cancelBtn() {
    top.window.parent.location.reload();
}
